-- Catálogo de demostración: unos 20 productos por tienda, con variantes, existencias, descuentos y mezcla de entrega express / programada.
-- Idempotente: no repite un producto que la tienda ya tenga (mismo nombre) ni una categoría que ya exista.
--   * express: peso ≤ 5 kg, lado ≤ 45 cm, suma de medidas ≤ 100 cm y fuera de categorías «solo programado».
--   * programado: productos pesados, voluminosos, por encargo (validation_days) o de la categoría «Electrodomésticos y muebles».
--   * descuento: la variante guarda el precio de lista en compare_at_price y un precio actual de al menos 5 % menos.
-- Generado por scratchpad/gen.mjs. No toca tiendas de pruebas E2E.

begin;

insert into commerce.master_items (kind, name, programado_only)
select 'categoria', c.name, c.programado_only
from (values
  ('Artesanías', false),
  ('Electrónica y tecnología', false),
  ('Electrodomésticos y muebles', true),
  ('Ropa y accesorios', false),
  ('Abarrotes y bebidas', false),
  ('Repostería y postres', false)
) as c(name, programado_only)
where not exists (select 1 from commerce.master_items m where m.kind = 'categoria' and lower(btrim(m.name)) = lower(c.name));

